argv:
$ErrorActionPreference='Stop'
Write-Output '===BRIDGE_STATUS==='
try { (Invoke-RestMethod 'http://127.0.0.1:17448/api/status' -TimeoutSec 8) | ConvertTo-Json -Compress -Depth 8 } catch { Write-Output ('ERR|status|'+$_.Exception.Message) }
Write-Output '===KNOWN_PROJECT_CHATS==='
$cfg='E:\WebAIBridge\app\data\supervisor-watchdog.json'
if(Test-Path $cfg){
  $c=Get-Content $cfg -Raw|ConvertFrom-Json
  foreach($x in @($c.knownProjectChats)){
    [pscustomobject]@{id=$x.id;name=$x.name;url=$x.url;profileId=$x.profileId;branch=$x.branch;gitHead=$x.gitHead;repository=$x.repository} | ConvertTo-Json -Compress -Depth 4
  }
}else{Write-Output 'NO_CONFIG'}
Write-Output '===MANAGED_CHAT_STATUS==='
$ms='E:\WebAIBridge\app\data\managed-chat-status.json'
if(Test-Path $ms){
  $m=Get-Content $ms -Raw|ConvertFrom-Json
  foreach($x in @($m)){[pscustomobject]@{id=$x.id;name=$x.name;url=$x.url;profileId=$x.profileId;generating=$x.generating;hasDraft=$x.hasDraft;highMode=$x.highMode} | ConvertTo-Json -Compress -Depth 4}
}else{Write-Output 'NO_MANAGED_STATUS'}
Write-Output '===CDP_CHATGPT_TABS==='
try {
  $xs=Invoke-RestMethod 'http://127.0.0.1:17410/json/list' -TimeoutSec 8
  $xs | Where-Object {$_.url -like 'https://chatgpt.com/*'} | Select-Object id,title,url,type | ConvertTo-Json -Compress -Depth 4
} catch { Write-Output ('ERR|cdp|'+$_.Exception.Message) }
